def response(path: str, headers: dict[str, str] | None = None) -> tuple[int, str, dict[str, str]]:
    response_headers = dict(headers or {})
    response_headers["X-Content-Type-Options"] = "nosniff"
    if path == "/":
        return 200, "home", response_headers
    return 404, "not found", response_headers

import unittest

from web import response


class SecurityHeaderTests(unittest.TestCase):
    def test_nosniff_is_set_on_every_response(self) -> None:
        for path in ("/", "/missing"):
            self.assertEqual(response(path)[2]["X-Content-Type-Options"], "nosniff")


if __name__ == "__main__":
    unittest.main()
